sys_script_include.script:
var ProjectMCPProjectServiceSNC = Class.create();

ProjectMCPProjectServiceSNC.prototype = {

    initialize: function() {},

    getByNumber: function(number) {
        if (gs.nil(number)) {
            return {
                success: false,
                error: 'Missing project number',
                status: 400
            };
        }

        var gr = new GlideRecordSecure('pm_project');
        gr.addQuery('number', number);
        gr.setLimit(1);
        gr.query();

        if (!gr.next()) {
            return {
                success: false,
                error: 'Project not found',
                status: 404
            };
        }

        var project = this._extractCoreFields(gr);

        project.activity = this._getActivity(gr);

        return {
            success: true,
            data: project
        };
    },

    _extractCoreFields: function(gr) {
        var result = {};

        var coreFields = [
            'sys_id',
            'number',
            'short_description',
            'description',
            'business_case',
            'active',
            'state',
            'status',
            'phase',
            'percent_complete',
            'project_manager',
            'primary_portfolio',
            'primary_program',
            'approved_start_date',
            'approved_end_date',
            'start_date',
            'end_date',
            'work_start',
            'work_end'
        ];

        var displayFields = [
            'state',
            'status',
            'phase',
            'project_manager',
            'primary_portfolio',
            'primary_program'
        ];

        for (var i = 0; i < coreFields.length; i++) {
            var field = coreFields[i];

            // Allows this service to tolerate differences in installed
            // Project/SPM plugins or table configuration.
            if (!gr.isValidField(field)) {
                continue;
            }

            if (displayFields.indexOf(field) !== -1) {
                result[field] = this._getFieldValue(gr, field);
            } else {
                result[field] = gr.getValue(field) || '';
            }
        }

        return result;
    },

    _getActivity: function(gr) {
        var limit = 5;
        var activity = [];

        if (gr.isValidField('comments')) {
            var comments = gr.comments.getJournalEntry(limit);

            if (!gs.nil(comments)) {
                activity.push(comments);
            }
        }

        if (gr.isValidField('work_notes')) {
            var workNotes = gr.work_notes.getJournalEntry(limit);

            if (!gs.nil(workNotes)) {
                activity.push(workNotes);
            }
        }

        return activity.join('\n\n');
    },

    _getFieldValue: function(gr, field) {
        return {
            value: gr.getValue(field) || '',
            display_value: gr.getDisplayValue(field) || ''
        };
    },

    type: 'ProjectMCPProjectServiceSNC'
};
